library {
    // Return an exact rational unchanged. This is useful when a public API
    // wants to say explicitly that it preserves a proportion.
    fn identity_ratio(value: Ratio) -> Ratio { value }

    // Return a natural number unchanged.
    fn identity_nat(value: Nat) -> Nat { value }

    // Apply the second musical transformation, then the first.
    fn compose_music(first: Music -> Music, second: Music -> Music, value: Music) -> Music {
        first(second(value))
    }

    // Apply the second pitch function, then the first.
    fn compose_pitch(first: Pitch -> Pitch, second: Pitch -> Pitch, value: Pitch) -> Pitch {
        first(second(value))
    }
}

musa-stdlib:/std/list.musa.text:
library {
    // The natural numbers from zero up to, but not including, count.
    fn naturals(count: Nat) -> List<Nat> { range(count) }

    // Apply one pitch function to every member of a finite pitch list.
    fn map_pitches(function: Pitch -> Pitch, values: List<Pitch>) -> List<Pitch> {
        map(function, values)
    }

    // Keep the pitches for which predicate returns true.
    fn filter_pitches(predicate: Pitch -> Bool, values: List<Pitch>) -> List<Pitch> {
        filter(predicate, values)
    }

    // Repeat one contextual music value count times as finite data.
    fn repeat_music(value: Music, count: Nat) -> List<Music> { repeat(value, count) }
}

